const api=Object.freeze({list:()=>request('/api/v1/workspaces?page=1&pageSize=100'),detail:x=>request('/api/v1/workspaces/'+encodeURIComponent(x)),types:()=>request('/api/v1/workspace-field-types'),versions:x=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/versions'),roleVisibility:x=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/role-visibility'),saveRoleVisibility:(x,b)=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/role-visibility',{method:'PUT',body:b,mutation:true}),create:x=>request('/api/v1/workspaces',{method:'POST',body:x,mutation:true}),update:(x,b)=>request('/api/v1/workspaces/'+encodeURIComponent(x),{method:'PATCH',body:b,mutation:true}),addSection:(x,b)=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/sections',{method:'POST',body:b,mutation:true}),updateSection:(x,b)=>request('/api/v1/workspace-sections/'+encodeURIComponent(x),{method:'PATCH',body:b,mutation:true}),addField:(x,b)=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/fields',{method:'POST',body:b,mutation:true}),updateField:(x,b)=>request('/api/v1/workspace-fields/'+encodeURIComponent(x),{method:'PATCH',body:b,mutation:true}),picklists:()=>request('/api/v1/picklists'),picklistValues:x=>request('/api/v1/picklists/'+encodeURIComponent(x)+'/values'),createPicklist:b=>request('/api/v1/picklists',{method:'POST',body:b,mutation:true}),updatePicklist:(x,b)=>request('/api/v1/picklists/'+encodeURIComponent(x),{method:'PATCH',body:b,mutation:true}),archivePicklist:(x,b)=>request('/api/v1/picklists/'+encodeURIComponent(x)+'/archive',{method:'POST',body:b,mutation:true}),resetPreview:x=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/reset-preview'),reset:(x,b)=>request('/api/v1/workspaces/'+encodeURIComponent(x)+'/reset',{method:'POST',body:b,mutation:true})});
function style(){if(id('wm2Style'))return;const s=document.createElement('style');s.id='wm2Style';s.textContent='.wm2-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0}.wm2-toolbar .search{flex:1;min-width:210px}.wm2-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}.wm2-tile{border:1px solid var(--border);border-radius:12px;padding:14px;background:var(--surface);cursor:pointer;text-align:left;color:var(--text)}.wm2-tile:hover{border-color:var(--primary);box-shadow:var(--shadow-sm)}.wm2-tile-head{display:flex;justify-content:space-between;gap:8px}.wm2-badges{display:flex;gap:5px;flex-wrap:wrap;margin-top:9px}.wm2-detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:14px}.wm2-section{border:1px solid var(--border);border-radius:12px;background:var(--surface);margin-bottom:12px}.wm2-section-head{padding:11px 13px;background:var(--surface-secondary);border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:8px}.wm2-field{display:grid;grid-template-columns:minmax(180px,1fr) 145px 145px auto;gap:10px;align-items:center;padding:10px 13px;border-bottom:1px solid var(--border)}.wm2-field:last-child{border-bottom:0}.wm2-field-actions{display:flex;gap:5px;justify-content:flex-end;flex-wrap:wrap}.wm2-preview-section{border:1px solid var(--border);border-radius:10px;padding:12px;margin:10px 0}.wm2-preview-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.wm2-preview-field{border:1px dashed var(--border);border-radius:8px;padding:9px}.wm2-meta{display:grid;gap:8px}.wm2-meta div{padding:9px;border-radius:8px;background:var(--surface-secondary)}.wm2-help,.wm2-protected{display:block;font-size:11px;color:var(--muted);margin-top:3px}.wm2-empty{text-align:center;padding:32px;color:var(--muted)}@media(max-width:850px){.wm2-detail-grid{grid-template-columns:1fr}.wm2-field{grid-template-columns:1fr}.wm2-field-actions{justify-content:flex-start}.wm2-preview-fields{grid-template-columns:1fr}}';document.head.appendChild(s)}
const settingsPage={title:'Workspace Manager',desc:'Create and configure workspace metadata, sections, fields, lifecycle and factory defaults.',cat:'Data & System',icon:'+',keys:'workspace manager custom workspace metadata sections fields lifecycle factory reset'};
function settingsHead(){return '<div class="uia1-page-head"><div><div class="uia1-breadcrumb">Admin Settings <span>&gt;</span> Data &amp; System <span>&gt;</span> Workspace Manager</div><h2 tabindex="-1">Workspace Manager</h2><p>'+settingsPage.desc+'</p></div><span class="uia1-status">Ready</span></div>'}
function integrateSettings(){const operational=production(),shell=id('uia1Shell'),rail=document.querySelector('.uia1-rail'),mobile=id('uia1MobilePage');if(!shell)return operational;let pane=id('uia1Pane-workspaces');if(!pane){pane=document.createElement('section');pane.id='uia1Pane-workspaces';pane.className='uia1-pane';pane.hidden=true;id('uia1Content')?.appendChild(pane)}const root=id('wm2Root');if(root&&root.parentElement!==pane)pane.appendChild(root);if(rail&&!rail.querySelector('[data-uia1-page="workspaces"]')){const button=document.createElement('button');button.type='button';button.className='uia1-nav-item';button.dataset.uia1Page='workspaces';button.onclick=()=>openSettings();button.innerHTML='<span class="uia1-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 12h8M12 8v8"/></svg></span><span>Workspace Manager</span><span class="uia1-chevron">&gt;</span>';const custom=rail.querySelector('[data-uia1-page="customfields"]'),group=custom?.closest('.uia1-nav-group');if(group)custom.after(button);else rail.appendChild(button)}if(mobile&&!mobile.querySelector('option[value="workspaces"]')){const o=document.createElement('option');o.value='workspaces';o.textContent=settingsPage.cat+' - '+settingsPage.title;mobile.appendChild(o)}return operational}
function availabilityHtml(){if(!production()){const mode=window.schoolHubTransport?.getMode?.()||'Local',serverConnected=mode!=='Local';return '<div class="card"><div class="section-title"><div><h2>Workspace Manager</h2><div class="muted">Workspace configuration is always available here.</div></div><span class="badge badge-warning">'+ev(mode)+'</span></div><div class="notice"><b>PostgreSQL editing is not active.</b><br>'+(serverConnected?'You are connected to the server. Activate Server Production to load and edit workspace definitions.':'Continue to the server login, then activate Server Production. Local browser data will not be changed.')+'</div><button class="btn primary" style="margin-top:12px" onclick="schoolHubPhase12?.'+(serverConnected?'activateProduction':'beginProductionSetup')+'?.()">'+(serverConnected?'Activate Server Production':'Continue to Server Login')+'</button></div>'}return ''}
function openSettings(opts){ensure();const pane=id('uia1Pane-workspaces');if(!pane)return;document.querySelectorAll('.uia1-pane').forEach(x=>x.hidden=x!==pane);document.querySelectorAll('.uia1-nav-item').forEach(x=>{const on=x.dataset.uia1Page==='workspaces';x.classList.toggle('active',on);x.setAttribute('aria-current',on?'page':'false')});const mobile=id('uia1MobilePage');if(mobile)mobile.value='workspaces';if(!pane.querySelector(':scope > .uia1-page-head'))pane.insertAdjacentHTML('afterbegin',settingsHead());if(!opts?.noFocus){id('uia1Content')?.scrollTo(0,0);pane.querySelector('h2')?.focus({preventScroll:true})}const unavailable=availabilityHtml();if(unavailable){id('wm2Root').innerHTML=unavailable;return}loadCatalog()}
function retireLegacyPrefixControls(){['setStudentPrefix','setReceiptPrefix'].forEach(key=>{const input=id(key),field=input?.closest('.field');if(field){field.hidden=true;field.setAttribute('aria-hidden','true')}})}
function ensure(){style();id('wm2Nav')?.remove();let section=id('workspaceManager');if(!section){section=document.createElement('section');section.id='workspaceManager';section.className='section';section.hidden=true;section.innerHTML='<div id="wm2Root"></div>';document.querySelector('main.content')?.appendChild(section)}section.hidden=true;retireLegacyPrefixControls();integrateSettings();setTimeout(consolidateAdminSettings,0)}
function errorHtml(e){return '<div class="card"><h2>Workspace Manager unavailable</h2><div class="notice">'+ev(e?.message||e)+'</div><div class="muted" style="margin-top:8px">No browser-local workspace data was used.</div></div>'}
function formError(message){let box=id('wm2FormError');if(!box){box=document.createElement('div');box.id='wm2FormError';box.className='notice danger-text';box.setAttribute('role','alert');const input=id('wm2SectionName')||id('wm2FieldLabel');input?.closest('.form-grid')?.before(box)}if(box.isConnected)box.textContent=message;else alert(message)}
async function safe(fn){try{return await fn()}catch(e){if(e?.code==='RECORD_VERSION_CONFLICT'){alert('This workspace changed after it was loaded. The latest version will now be reloaded.');if(state.detail)await openWorkspace(state.detail.id);return}formError(e?.message||'The workspace operation could not be completed.');return null}}
async function loadCatalog(){if(!production())return;restoreDesignerMount();const root=id('wm2Root');if(!root)return;root.innerHTML='<div class="card">Loading PostgreSQL workspace catalogue…</div>';try{const [list,types,picklists]=await Promise.all([api.list(),api.types(),api.picklists()]);state.items=list.items||[];state.types=types.items||[];state.picklists=picklists.items||[];state.picklistSources=picklists.workspaceSources||[];renderCatalog()}catch(e){root.innerHTML=errorHtml(e)}}
function picklistSourceFields(key){return{students:[['id','Record ID'],['admissionNumber','Admission Number'],['name','Student Name'],['status','Status'],['classId','Class'],['sectionId','Section']],staff:[['id','Record ID'],['employeeNumber','Employee Number'],['name','Staff Name'],['status','Status']],classes:[['id','Record ID'],['name','Class Name'],['active','Active']]}[key]||[]}
function picklistValues(text){return String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const p=line.split('|');return{value:p[0].trim(),label:(p[1]||p[0]).trim(),filterValue:(p[2]||'').trim()||null}})}
async function openPicklistManager(){await safe(async()=>{if(!state.picklists.length){const r=await api.picklists();state.picklists=r.items||[];state.picklistSources=r.workspaceSources||[]}const root=id('wm2Root'),rows=state.picklists.map(x=>'<div class="wm3-list-row"><div><b>'+ev(x.name)+'</b><span class="wm2-help">'+ev(x.picklistKey)+' · '+ev(x.description||'No description')+'</span></div><div><span class="wm3-type">'+ev(x.sourceType==='Workspace'?'Workspace-backed':'Admin-defined')+'</span></div><div class="wm3-visibility">'+(x.sourceType==='AdminDefined'?x.values.length+' values':ev(state.items.find(w=>w.id===x.workspaceId)?.pluralName||'Workspace source'))+'</div><div class="wm3-actions"><button class="btn small" onclick="schoolHubWM2.previewPicklist(\''+ev(x.id)+'\')">Preview</button>'+(has('workspaces:configure')?'<button class="btn small" onclick="schoolHubWM2.openPicklist(\''+ev(x.id)+'\')">Edit</button><button class="btn small danger" onclick="schoolHubWM2.archivePicklist(\''+ev(x.id)+'\')">Archive</button>':'')+'</div></div>').join('');root.innerHTML='<div class="wm3-shell"><div class="wm3-catalog-head"><div><div class="wm2-help">Administration / Workspace Manager / Picklist Manager</div><h2 class="wm3-title">Picklist Manager</h2><div class="wm3-subtitle">Create reusable choices for custom fields from administrator values or live Workspace records.</div></div><div class="wm3-actions"><button class="btn" onclick="schoolHubWM2.loadCatalog()">← Workspaces</button>'+(has('workspaces:configure')?'<button class="btn primary" onclick="schoolHubWM2.openPicklist()">+ Create Picklist</button>':'')+'</div></div><div class="wm3-panel" style="margin-top:18px"><div class="wm3-note"><b>Reusable and future-safe.</b> New radio and selection fields use these lists. Existing inline values remain compatible.</div><div class="wm3-list"><div class="wm3-list-head"><span>Picklist</span><span>Source</span><span>Values</span><span>Actions</span></div>'+(rows||'<div class="wm3-empty">No Picklists yet. Create the first reusable list.</div>')+'</div></div></div>'})}
function picklistSourceChanged(){const source=id('wm2PicklistSource')?.value||'AdminDefined',workspace=id('wm2PicklistWorkspace')?.value||'';document.querySelectorAll('.wm2-picklist-admin').forEach(x=>x.style.display=source==='AdminDefined'?'':'none');document.querySelectorAll('.wm2-picklist-workspace').forEach(x=>x.style.display=source==='Workspace'?'':'none');if(source==='Workspace'){const key=state.items.find(x=>x.id===workspace)?.workspaceKey,fields=picklistSourceFields(key),options=fields.map(x=>'<option value="'+ev(x[0])+'">'+ev(x[1])+'</option>').join('');for(const target of ['wm2PicklistValueField','wm2PicklistLabelField','wm2PicklistFilterField']){const select=id(target),current=select?.dataset.current||select?.value;if(select){select.innerHTML=(target==='wm2PicklistFilterField'?'<option value="">No filter column</option>':'')+options;if(current)select.value=current}}}}
function openPicklist(picklistId){const p=state.picklists.find(x=>x.id===picklistId),workspaces=state.items.filter(x=>state.picklistSources.includes(x.workspaceKey)),values=(p?.values||[]).map(x=>x.value+' | '+x.label+(x.filterValue?' | '+x.filterValue:'')).join('\n');openModal(p?'Edit Picklist':'Create Picklist','<div class="form-grid"><div class="field"><label>Name</label><input id="wm2PicklistName" value="'+ev(p?.name)+'"></div><div class="field"><label>Stable key</label><input id="wm2PicklistKey" value="'+ev(p?.picklistKey)+'" '+(p?'disabled':'')+'></div><div class="field span2"><label>Description</label><textarea id="wm2PicklistDescription">'+ev(p?.description)+'</textarea></div><div class="field"><label>Source</label><select id="wm2PicklistSource" onchange="schoolHubWM2.picklistSourceChanged()" '+(p?'disabled':'')+'><option value="AdminDefined" '+(p?.sourceType!=='Workspace'?'selected':'')+'>Values defined by admin</option><option value="Workspace" '+(p?.sourceType==='Workspace'?'selected':'')+'>Records from a Workspace</option></select></div><div class="field wm2-picklist-workspace"><label>Workspace</label><select id="wm2PicklistWorkspace" onchange="schoolHubWM2.picklistSourceChanged()" '+(p?'disabled':'')+'>'+workspaces.map(x=>'<option value="'+ev(x.id)+'" '+(p?.workspaceId===x.id?'selected':'')+'>'+ev(x.pluralName)+'</option>').join('')+'</select></div><div class="field span2 wm2-picklist-admin"><label>Values — one per line as value | label | optional filter value</label><textarea id="wm2PicklistValues" rows="10">'+ev(values)+'</textarea></div><div class="field wm2-picklist-workspace"><label>Stored value</label><select id="wm2PicklistValueField" data-current="'+ev(p?.valueFieldKey)+'" '+(p?'disabled':'')+'></select></div><div class="field wm2-picklist-workspace"><label>Display label</label><select id="wm2PicklistLabelField" data-current="'+ev(p?.labelFieldKey)+'" '+(p?'disabled':'')+'></select></div><div class="field wm2-picklist-workspace"><label>Optional filter value</label><select id="wm2PicklistFilterField" data-current="'+ev(p?.filterFieldKey)+'" '+(p?'disabled':'')+'></select></div></div><button class="btn primary" onclick="schoolHubWM2.savePicklist(\''+ev(p?.id||'')+'\')">Save Picklist</button>');picklistSourceChanged()}
async function savePicklist(picklistId){await safe(async()=>{const existing=state.picklists.find(x=>x.id===picklistId),source=id('wm2PicklistSource').value,base={picklistKey:id('wm2PicklistKey').value.trim(),name:id('wm2PicklistName').value.trim(),description:id('wm2PicklistDescription').value.trim(),sourceType:source};let body;if(existing)body={name:base.name,description:base.description,version:existing.version,...(existing.sourceType==='AdminDefined'?{values:picklistValues(id('wm2PicklistValues').value)}:{})};else if(source==='AdminDefined')body={...base,values:picklistValues(id('wm2PicklistValues').value)};else body={...base,workspaceId:id('wm2PicklistWorkspace').value,valueFieldKey:id('wm2PicklistValueField').value,labelFieldKey:id('wm2PicklistLabelField').value,filterFieldKey:id('wm2PicklistFilterField').value||null};await(existing?api.updatePicklist(existing.id,body):api.createPicklist(body));const r=await api.picklists();state.picklists=r.items||[];closeModal();showToast('Picklist saved.');await openPicklistManager()})}
async function previewPicklist(picklistId){await safe(async()=>{const p=state.picklists.find(x=>x.id===picklistId),r=await api.picklistValues(picklistId);openModal('Preview — '+p.name,'<div class="notice">Read-only preview of the values currently available to custom fields.</div><div class="table-wrap"><table><thead><tr><th>Value</th><th>Label</th><th>Filter</th></tr></thead><tbody>'+((r.items||[]).map(x=>'<tr><td>'+ev(x.value)+'</td><td>'+ev(x.label)+'</td><td>'+ev(x.filterValue||'—')+'</td></tr>').join('')||'<tr><td colspan="3">No active values.</td></tr>')+'</tbody></table></div>')})}
async function archivePicklist(picklistId){const p=state.picklists.find(x=>x.id===picklistId);if(!p||!confirm('Archive Picklist "'+p.name+'"?'))return;await safe(async()=>{await api.archivePicklist(p.id,{version:p.version});state.picklists=(await api.picklists()).items||[];showToast('Picklist archived.');await openPicklistManager()})}
function filtered(){let rows=state.items.filter(x=>(!state.search||(x.name+' '+x.pluralName+' '+x.description+' '+x.workspaceKey).toLowerCase().includes(state.search.toLowerCase()))&&(!state.category||x.category===state.category)&&(!state.type||x.workspaceType===state.type)&&(!state.status||x.status===state.status));const sorts={name:(a,b)=>a.pluralName.localeCompare(b.pluralName),category:(a,b)=>a.category.localeCompare(b.category)||a.pluralName.localeCompare(b.pluralName),type:(a,b)=>a.workspaceType.localeCompare(b.workspaceType)||a.pluralName.localeCompare(b.pluralName),version:(a,b)=>b.definitionVersion-a.definitionVersion};return rows.sort(sorts[state.sort]||sorts.name)}
function renderCatalog(){state.detail=null;const root=id('wm2Root'),categories=[...new Set(state.items.map(x=>x.category))].sort(),rows=filtered();root.innerHTML='<div class="section-title"><div><h2>Workspace Manager</h2><div class="muted">Configure PostgreSQL workspace metadata. Existing module records and navigation are unchanged.</div></div>'+(has('workspaces:create')?'<button class="btn primary" onclick="schoolHubWM2.openCreate()">+ Create Workspace</button>':'')+'</div><div class="notice"><b>Existing fields mapped:</b> Built-in module fields are visible as protected definitions. Custom fields and safe display settings remain configurable without replacing operational records.</div><div class="wm2-toolbar"><input class="search" aria-label="Search workspaces" placeholder="Search workspaces…" value="'+ev(state.search)+'" oninput="schoolHubWM2.filter(\'search\',this.value)"><select aria-label="Category" onchange="schoolHubWM2.filter(\'category\',this.value)"><option value="">All categories</option>'+categories.map(x=>'<option '+(state.category===x?'selected':'')+'>'+ev(x)+'</option>').join('')+'</select><select aria-label="Type" onchange="schoolHubWM2.filter(\'type\',this.value)"><option value="">All types</option>'+['BuiltIn','Custom'].map(x=>'<option '+(state.type===x?'selected':'')+'>'+x+'</option>').join('')+'</select><select aria-label="Status" onchange="schoolHubWM2.filter(\'status\',this.value)"><option value="">All statuses</option>'+['Draft','Active','Archived'].map(x=>'<option '+(state.status===x?'selected':'')+'>'+x+'</option>').join('')+'</select><select aria-label="Sort" onchange="schoolHubWM2.filter(\'sort\',this.value)">'+[['name','Name'],['category','Category'],['type','Type'],['version','Latest version']].map(x=>'<option value="'+x[0]+'" '+(state.sort===x[0]?'selected':'')+'>Sort: '+x[1]+'</option>').join('')+'</select></div><div class="muted" style="margin-bottom:9px">'+rows.length+' of '+state.items.length+' workspaces</div><div class="wm2-grid">'+(rows.map(x=>'<button class="wm2-tile" onclick="schoolHubWM2.openWorkspace(\''+ev(x.id)+'\')"><span class="wm2-tile-head"><span><b>'+ev(x.pluralName)+'</b><span class="wm2-help">'+ev(x.workspaceKey)+'</span></span><span class="badge">v'+ev(x.definitionVersion)+'</span></span><span class="muted" style="display:block;margin-top:7px">'+ev(x.description||'No description')+'</span><span class="wm2-badges"><span class="badge">'+ev(x.category)+'</span><span class="badge">'+ev(x.workspaceType)+'</span><span class="badge '+(x.status==='Active'?'badge-success':x.status==='Archived'?'badge-neutral':'badge-warning')+'">'+ev(x.status)+'</span>'+(x.system?'<span class="badge">Protected</span>':'')+'</span></button>').join('')||'<div class="card wm2-empty">No workspaces match these filters.</div>')+'</div>'}
function filter(k,v){state[k]=v;renderCatalog()}function keyFrom(v){return String(v||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)}
function openCreate(){openModal('Create Custom Workspace','<div class="notice">A new workspace starts as Draft. This creates metadata only.</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Workspace name</label><input id="wm2NewName" oninput="if($(\'wm2NewKey\').dataset.auto===\'true\')$(\'wm2NewKey\').value=schoolHubWM2.keyFrom(this.value)"></div><div class="field"><label>Plural name</label><input id="wm2NewPlural"></div><div class="field"><label>Stable key</label><input id="wm2NewKey" data-auto="true" onchange="this.dataset.auto=\'false\'"><div class="wm2-help">Cannot be changed after creation.</div></div><div class="field"><label>Category</label><input id="wm2NewCategory" value="Custom"></div><div class="field span2"><label>Description</label><textarea id="wm2NewDescription"></textarea></div></div><button class="btn primary" onclick="schoolHubWM2.saveCreate()">Create Draft Workspace</button>')}
async function saveCreate(){await safe(async()=>{const created=await api.create({workspaceKey:id('wm2NewKey').value.trim(),name:id('wm2NewName').value.trim(),pluralName:id('wm2NewPlural').value.trim(),category:id('wm2NewCategory').value.trim(),description:id('wm2NewDescription').value.trim()});closeModal();state.items=(await api.list()).items||[];showToast('Draft workspace created.');await openWorkspace(created.id)})}
async function openWorkspace(x){const root=id('wm2Root');root.innerHTML='<div class="card">Loading workspace definition…</div>';try{state.detail=await api.detail(x);renderDetail()}catch(e){root.innerHTML=errorHtml(e)}}function allFields(w=state.detail){return [...(w?.sections||[]).flatMap(s=>s.fields||[]),...(w?.unassignedFields||[])]}function renderDetail(){const w=state.detail,root=id('wm2Root');if(!w)return renderCatalog();const actions='<button class="btn" onclick="schoolHubWM2.loadCatalog()">← Catalogue</button> <button class="btn" onclick="schoolHubWM2.preview()">Preview</button> <button class="btn" onclick="schoolHubWM2.history()">Version History</button> '+(has('workspaces:configure')?'<button class="btn" onclick="schoolHubWM2.editWorkspace()">Edit Workspace</button> ':'')+(w.system&&has('workspaces:reset')?'<button class="btn danger" onclick="schoolHubWM2.resetPreview()">Reset to Factory</button>':'');root.innerHTML='<div class="section-title"><div><h2>'+ev(w.pluralName)+' '+(w.system?'<span class="badge">Protected built-in</span>':'<span class="badge">Custom</span>')+'</h2><div class="muted">'+ev(w.description)+'</div></div><div>'+actions+'</div></div><div class="wm2-detail-grid"><div><div class="section-title"><h3>Sections and Fields</h3>'+(has('workspaces:configure')?'<button class="btn primary small" onclick="schoolHubWM2.openSection()">+ Add Section</button> <button class="btn primary small" onclick="schoolHubWM2.openField()">+ Add Custom Field</button>':'')+'</div>'+((w.sections||[]).map((s,i)=>sectionHtml(s,i,w.sections.length)).join('')||'<div class="card wm2-empty">No sections yet.</div>')+(w.unassignedFields?.length?'<div class="wm2-section"><div class="wm2-section-head"><b>Unassigned Fields</b></div>'+w.unassignedFields.map((f,i)=>fieldHtml(f,i,w.unassignedFields.length)).join('')+'</div>':'')+'</div><aside class="card wm2-meta"><h3>Definition</h3><div><small>Stable key</small><br><b>'+ev(w.workspaceKey)+'</b></div><div><small>Lifecycle</small><br><span class="badge '+(w.status==='Active'?'badge-success':'')+'">'+ev(w.status)+'</span></div><div><small>Category</small><br><b>'+ev(w.category)+'</b></div><div><small>Metadata version</small><br><b>'+ev(w.definitionVersion)+'</b></div><div><small>Factory version</small><br><b>'+ev(w.factoryVersion||'Not applicable')+'</b></div><div><small>Last modified</small><br>'+ev(w.updatedAt||'Not available')+'</div>'+lifecycleHtml(w)+'</aside></div>'}
function lifecycleHtml(w){if(w.system||!has('workspaces:configure'))return '<div class="wm2-protected">Built-in workspace lifecycle is fixed as Active.</div>';if(w.status==='Draft')return '<button class="btn primary" onclick="schoolHubWM2.setStatus(\'Active\')">Activate Metadata</button>';if(w.status==='Active'&&has('workspaces:archive'))return '<button class="btn danger" onclick="schoolHubWM2.setStatus(\'Archived\')">Archive Workspace</button>';if(w.status==='Archived')return '<button class="btn" onclick="schoolHubWM2.setStatus(\'Draft\')">Return to Draft</button>';return ''}
function sectionHtml(s,i,total){const edit=has('workspaces:configure');return '<div class="wm2-section"><div class="wm2-section-head"><span><b>'+ev(s.name)+'</b> '+(s.system?'<span class="badge">System</span>':'')+(s.enabled===false?'<span class="badge badge-neutral">Archived</span>':'')+'<span class="wm2-help">'+ev(s.sectionKey)+'</span></span><span>'+(edit?'<button class="btn small" onclick="schoolHubWM2.openSection(\''+ev(s.id)+'\')">Edit</button> <button class="btn small" '+(i===0?'disabled':'')+' onclick="schoolHubWM2.moveSection('+i+',-1)">↑</button> <button class="btn small" '+(i===total-1?'disabled':'')+' onclick="schoolHubWM2.moveSection('+i+',1)">↓</button> '+(!s.system&&s.enabled!==false?'<button class="btn small danger" onclick="schoolHubWM2.archiveSection(\''+ev(s.id)+'\')">Archive</button> ':'')+'<button class="btn primary small" onclick="schoolHubWM2.openField(null,\''+ev(s.id)+'\')">+ Field</button>':'')+'</span></div>'+((s.fields||[]).map((f,n)=>fieldHtml(f,n,s.fields.length)).join('')||'<div class="wm2-empty">No fields in this section.</div>')+'</div>'}
function fieldHtml(f,i,total){const edit=has('workspaces:configure'),protectedArchive=(f.protectedProperties||[]).includes('archived');return '<div class="wm2-field"><span><b>'+ev(f.label)+'</b>'+(f.required?' <span class="danger-text">*</span>':'')+' '+(f.system?'<span class="badge">System</span>':'')+(f.archived?'<span class="badge badge-neutral">Archived</span>':'')+'<span class="wm2-help">'+ev(f.fieldKey)+'</span></span><span>'+ev(labels[f.fieldType]||f.fieldType)+'</span><span class="muted">'+[f.screenVisible?'Screen':'',f.previewVisible?'Preview':'',f.printVisible?'Print':'',f.searchable?'Search':''].filter(Boolean).join(' · ')+'</span><span class="wm2-field-actions">'+(edit?'<button class="btn small" onclick="schoolHubWM2.openField(\''+ev(f.id)+'\')">Edit</button><button class="btn small" onclick="schoolHubWM2.copyField(\''+ev(f.id)+'\')">Copy</button><button class="btn small" '+(i===0?'disabled':'')+' onclick="schoolHubWM2.moveField(\''+ev(f.sectionId||'')+'\','+i+',-1)">↑</button><button class="btn small" '+(i===total-1?'disabled':'')+' onclick="schoolHubWM2.moveField(\''+ev(f.sectionId||'')+'\','+i+',1)">↓</button>'+(!f.archived&&!protectedArchive?'<button class="btn small danger" onclick="schoolHubWM2.archiveField(\''+ev(f.id)+'\')">Archive</button>':''):'')+'</span></div>'}
function editWorkspace(){const w=state.detail;openModal('Edit Workspace','<div class="form-grid"><div class="field"><label>Name</label><input id="wm2EditName" value="'+ev(w.name)+'"></div><div class="field"><label>Plural name</label><input id="wm2EditPlural" value="'+ev(w.pluralName)+'"></div><div class="field"><label>Stable key</label><input value="'+ev(w.workspaceKey)+'" disabled><div class="wm2-help">Protected immutable identity.</div></div><div class="field"><label>Category</label><input id="wm2EditCategory" value="'+ev(w.category)+'"></div><div class="field span2"><label>Description</label><textarea id="wm2EditDescription">'+ev(w.description)+'</textarea></div></div><button class="btn primary" onclick="schoolHubWM2.saveWorkspace()">Save Workspace</button>')}
async function saveWorkspace(){await safe(async()=>{const w=state.detail;state.detail=await api.update(w.id,{name:id('wm2EditName').value.trim(),pluralName:id('wm2EditPlural').value.trim(),category:id('wm2EditCategory').value.trim(),description:id('wm2EditDescription').value.trim(),version:w.version});closeModal();renderDetail();showToast('Workspace saved.')})}
async function setStatus(status){const w=state.detail,verb=status==='Active'?'activate':status==='Archived'?'archive':'return to Draft';if(!confirm('Confirm '+verb+' for "'+w.pluralName+'"? This changes metadata status only.'))return;await safe(async()=>{state.detail=await api.update(w.id,{status,version:w.version});renderDetail();showToast('Workspace status changed to '+status+'.')})}
function sectionLayoutControls(s){const layouts=s?.layouts||{},views={create:'Create form',edit:'Edit form',record:'Record view',print:'Print view'};return '<div class="field span2"><b>Per-view layouts</b><div class="wm2-help">Each view keeps its own visibility, order and column count.</div><div class="wm3-ready-grid" style="margin-top:10px">'+Object.entries(views).map(([key,label])=>{const cfg=layouts[key]||{},fallbackVisible=key==='print'?s?.printVisible!==false:s?.screenVisible!==false;return '<div class="wm3-ready-card"><b>'+label+'</b><label class="wm3-switch"><input id="wm2LayoutVisible_'+key+'" type="checkbox" '+((cfg.visible??fallbackVisible)?'checked':'')+'> Visible</label><label class="wm3-switch">Columns <select id="wm2LayoutColumns_'+key+'">'+[1,2,3].map(x=>'<option '+((cfg.columns||s?.layoutColumns||2)===x?'selected':'')+'>'+x+'</option>').join('')+'</select></label><label class="wm3-switch">Order <input id="wm2LayoutOrder_'+key+'" type="number" min="0" max="10000" value="'+(cfg.order??s?.order??0)+'"></label></div>'}).join('')+'</div></div>'}
function readSectionLayouts(s){const result={};for(const key of ['create','edit','record','print'])result[key]={visible:id('wm2LayoutVisible_'+key).checked,columns:Number(id('wm2LayoutColumns_'+key).value),order:Number(id('wm2LayoutOrder_'+key).value),fieldOrder:s?.layouts?.[key]?.fieldOrder||[]};return result}
function openSection(sectionId){const w=state.detail,s=w.sections.find(x=>x.id===sectionId);openModal(s?'Edit Section':'Add Section','<div class="form-grid"><div class="field"><label>Section name</label><input id="wm2SectionName" oninput="if(!document.getElementById(\'wm2SectionKey\').disabled)document.getElementById(\'wm2SectionKey\').value=schoolHubWM2.keyFrom(this.value)" value="'+ev(s?.name)+'"></div><div class="field"><label>Stable key</label><input id="wm2SectionKey" value="'+ev(s?.sectionKey)+'" '+(s?'disabled':'')+'><div class="wm2-help">Cannot be changed after creation.</div></div><div class="field span2"><label>Description</label><textarea id="wm2SectionDescription">'+ev(s?.description)+'</textarea></div><div class="field"><label>Layout columns</label><select id="wm2SectionColumns">'+[1,2,3].map(x=>'<option '+((s?.layoutColumns||2)===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label><input id="wm2SectionScreen" type="checkbox" '+(s?.screenVisible!==false?'checked':'')+'> Visible on screen</label><label><input id="wm2SectionPrint" type="checkbox" '+(s?.printVisible!==false?'checked':'')+'> Visible in print preview</label></div>'+sectionLayoutControls(s)+'</div><button class="btn primary" onclick="schoolHubWM2.saveSection(\''+ev(s?.id||'')+'\')">Save Section</button>')}
async function saveSection(sectionId){await safe(async()=>{if(!id('wm2SectionName').value.trim())throw new Error('Enter a section name.');if(!/^[a-z][a-z0-9-]{1,79}$/.test(keyFrom(id('wm2SectionKey').value||id('wm2SectionName').value)))throw new Error('Use a key of 2–80 characters, starting with a letter, with lowercase letters, numbers or hyphens.');const s=state.detail.sections.find(x=>x.id===sectionId),base={layouts:readSectionLayouts(s),name:id('wm2SectionName').value.trim(),description:id('wm2SectionDescription').value.trim(),layoutColumns:Number(id('wm2SectionColumns').value),screenVisible:id('wm2SectionScreen').checked,printVisible:id('wm2SectionPrint').checked};state.detail=s?await api.updateSection(s.id,{...base,version:s.version}):await api.addSection(state.detail.id,{...base,sectionKey:keyFrom(id('wm2SectionKey').value||base.name),order:state.detail.sections.length+1,workspaceVersion:state.detail.version});closeModal();renderDetail();showToast('Section saved.')})}
async function archiveSection(sectionId){const s=state.detail.sections.find(x=>x.id===sectionId);if(!s||!confirm('Archive section "'+s.name+'"? Its metadata and fields remain available for recovery.'))return;await safe(async()=>{state.detail=await api.updateSection(s.id,{enabled:false,version:s.version});renderDetail()})}
async function moveSection(i,d){const a=state.detail.sections,j=i+d;if(j<0||j>=a.length)return;await safe(async()=>{let one=a[i],two=a[j],next=await api.updateSection(one.id,{order:two.order,version:one.version});two=next.sections.find(x=>x.id===two.id);state.detail=await api.updateSection(two.id,{order:one.order,version:two.version});renderDetail()})}
function typeOptions(selected){return state.types.map(x=>'<option value="'+ev(x.type)+'" '+(x.type===selected?'selected':'')+'>'+ev(labels[x.type]||x.type)+'</option>').join('')+deferred.map(x=>'<option disabled>'+ev(x)+' - future phase</option>').join('')}function openField(fieldId,sectionId){const f=allFields().find(x=>x.id===fieldId),ps=new Set(f?.protectedProperties||[]),type=f?.fieldType||'text',sections=state.detail.sections.filter(x=>x.enabled!==false),cfg=f?.configuration||{},options=(f?.options||[]).map(x=>x.value+(x.label!==x.value?' | '+x.label:'')).join('\n'),targets=state.items.filter(x=>x.status!=='Archived'),axis=x=>(Array.isArray(x)?x:[]).map(v=>v.key+' | '+v.label).join('\n'),picklistChoices=state.picklists.map(x=>'<option value="'+ev(x.id)+'" '+(cfg.picklistId===x.id?'selected':'')+'>'+ev(x.name)+' ('+ev(x.sourceType==='Workspace'?'Workspace':'Admin')+')</option>').join(''),controlFields=allFields().filter(x=>x.id!==f?.id&&!x.archived).map(x=>'<option value="'+ev(x.fieldKey)+'" '+(cfg.picklistFilterFieldKey===x.fieldKey?'selected':'')+'>'+ev(x.label)+'</option>').join('');openModal(f?'Edit Field':'Add Field','<input id="wm2FieldId" type="hidden" value="'+ev(f?.id)+'"><div class="form-grid"><div class="field"><label>Display label</label><input id="wm2FieldLabel" value="'+ev(f?.label)+'"></div><div class="field"><label>Stable key</label><input id="wm2FieldKey" value="'+ev(f?.fieldKey)+'" '+(f?'disabled':'')+'><div class="wm2-help">Cannot be changed after creation.</div></div><div class="field"><label>Section</label><select id="wm2FieldSection"><option value="">Unassigned</option>'+sections.map(x=>'<option value="'+ev(x.id)+'" '+((f?.sectionId||sectionId)===x.id?'selected':'')+'>'+ev(x.name)+'</option>').join('')+'</select></div><div class="field"><label>Field type</label><select id="wm2FieldType" onchange="schoolHubWM2.fieldTypeChanged()" '+(ps.has('fieldType')?'disabled title="Protected system property"':'')+'>'+typeOptions(type)+'</select>'+(ps.has('fieldType')?'<div class="wm2-protected">System field type is protected.</div>':'')+'</div><div class="field span2"><label>Description</label><textarea id="wm2FieldDescription">'+ev(f?.description)+'</textarea></div><div class="field span2"><label>Help text</label><input id="wm2FieldHelp" value="'+ev(f?.helpText)+'"></div><div class="field wm2-placeholder"><label>Placeholder</label><input id="wm2FieldPlaceholder" value="'+ev(f?.placeholder)+'"></div><div class="field"><label>Width</label><select id="wm2FieldWidth">'+[['full','Full'],['half','Half'],['third','One third'],['twoThirds','Two thirds']].map(x=>'<option value="'+x[0]+'" '+((f?.width||'full')===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></div><div class="field wm2-range"><label>Minimum</label><input id="wm2FieldMin" value="'+ev(cfg.min)+'"></div><div class="field wm2-range"><label>Maximum</label><input id="wm2FieldMax" value="'+ev(cfg.max)+'"></div><div class="field wm2-picklist-field"><label>Picklist</label><select id="wm2FieldPicklist"><option value="">'+((f?.options||[]).length?'Legacy inline values':'Select a Picklist')+'</option>'+picklistChoices+'</select><div class="wm2-help">Managed centrally in Picklist Manager.</div></div><div class="field wm2-picklist-field"><label>Selection behavior</label><select id="wm2PicklistMode" onchange="schoolHubWM2.picklistModeChanged()"><option value="single" '+((cfg.picklistMode||(type==='multiSelect'?'multiple':'single'))==='single'?'selected':'')+'>Single selection</option><option value="multiple" '+((cfg.picklistMode||(type==='multiSelect'?'multiple':'single'))==='multiple'?'selected':'')+'>Multiple selection</option><option value="filtered" '+(cfg.picklistMode==='filtered'?'selected':'')+'>Filtered selection</option></select></div><div class="field wm2-picklist-field wm2-picklist-filter"><label>Filter controlled by field</label><select id="wm2PicklistFilterField"><option value="">Select controlling field</option>'+controlFields+'</select></div><div class="field wm2-picklist-field wm2-picklist-filter"><div class="wm2-help">The controlling field value is matched to each Picklist value&#39;s filter value.</div></div><div class="field wm2-reference-field"><label>Target Workspace</label><select id="wm2ReferenceTarget"><option value="">Select Workspace</option>'+targets.map(x=>'<option value="'+ev(x.id)+'" '+(cfg.targetWorkspaceId===x.id?'selected':'')+'>'+ev(x.pluralName)+'</option>').join('')+'</select></div><div class="field wm2-reference-field"><label>Relationship Type</label><select id="wm2RelationshipType">'+[['lookup','Lookup'],['parentChild','Parent / child'],['manyToMany','Many to many']].map(x=>'<option value="'+x[0]+'" '+((cfg.relationshipType||'lookup')===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></div><div class="field wm2-reference-field"><label>Selection Mode</label><select id="wm2ReferenceSelection"><option value="single" '+(cfg.selectionMode!=='multiple'?'selected':'')+'>Single record</option><option value="multiple" '+(cfg.selectionMode==='multiple'?'selected':'')+'>Multiple records</option></select></div><div class="field wm2-reference-field"><label>Target display field key</label><input id="wm2ReferenceField" value="'+ev(cfg.targetFieldKey||'')+'" placeholder="Optional, for example name"></div><div class="field wm2-matrix-field"><label>Rows</label><textarea id="wm2MatrixRows" placeholder="attendance | Attendance">'+ev(axis(cfg.rows))+'</textarea><div class="wm2-help">One stable key and label per line.</div></div><div class="field wm2-matrix-field"><label>Columns</label><textarea id="wm2MatrixColumns" placeholder="term1 | Term 1">'+ev(axis(cfg.columns))+'</textarea><div class="wm2-help">One stable key and label per line.</div></div><div class="field wm2-matrix-field"><label>Cell type</label><select id="wm2MatrixCellType">'+[['text','Text'],['integer','Integer'],['decimal','Decimal'],['checkbox','Checkbox'],['singleSelect','Single selection']].map(x=>'<option value="'+x[0]+'" '+((cfg.cellType||'text')===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></div><div class="field span2"><div class="quick"><label><input id="wm2FieldRequired" type="checkbox" '+(f?.required?'checked':'')+' '+(ps.has('required')?'disabled data-protected="true"':'')+'> Required</label><label><input id="wm2FieldScreen" type="checkbox" '+(f?.screenVisible!==false?'checked':'')+'> Screen</label><label><input id="wm2FieldPreview" type="checkbox" '+(f?.previewVisible?'checked':'')+'> Preview</label><label><input id="wm2FieldPrint" type="checkbox" '+(f?.printVisible!==false?'checked':'')+'> Print</label><label><input id="wm2FieldSearch" type="checkbox" '+(f?.searchable?'checked':'')+'> Search</label><label><input id="wm2FieldFilter" type="checkbox" '+(f?.filterable?'checked':'')+'> Filter</label></div></div></div><button class="btn primary" onclick="schoolHubWM2.saveField()">Save Field</button>');fieldTypeChanged()}
function fieldTypeChanged(){const type=id('wm2FieldType')?.value;if(!type)return;document.querySelectorAll('.wm2-picklist-field').forEach(x=>x.style.display=['radio','singleSelect','multiSelect'].includes(type)?'':'none');document.querySelectorAll('.wm2-range').forEach(x=>x.style.display=['integer','decimal','currency','date','dateTime'].includes(type)?'':'none');document.querySelectorAll('.wm2-placeholder').forEach(x=>x.style.display=['text','longText','email','phone','url'].includes(type)?'':'none');document.querySelectorAll('.wm2-reference-field').forEach(x=>x.style.display=type==='workspaceReference'?'':'none');document.querySelectorAll('.wm2-matrix-field').forEach(x=>x.style.display=type==='matrix'?'':'none');const mode=id('wm2PicklistMode');if(mode&&mode.value!=='filtered')mode.value=type==='multiSelect'?'multiple':'single';picklistModeChanged();if(id('wm2FieldRequired')&&!id('wm2FieldRequired').dataset.protected)id('wm2FieldRequired').disabled=['heading','staticText'].includes(type)}
function picklistModeChanged(){const filtered=id('wm2PicklistMode')?.value==='filtered';document.querySelectorAll('.wm2-picklist-filter').forEach(x=>x.style.display=filtered?'':'none')}
function parseOptions(text){return String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const p=line.split('|');return{value:p[0].trim(),label:(p[1]||p[0]).trim()}})}
function parseAxis(text){const rows=parseOptions(text);if(!rows.length)throw new Error('Add at least one Matrix row and column.');for(const x of rows)if(!/^[a-z][A-Za-z0-9]{0,79}$/.test(x.value))throw new Error('Matrix keys must start with a lowercase letter and use letters or numbers.');return rows.map(x=>({key:x.value,label:x.label}))}
async function saveField(){await safe(async()=>{const f=allFields().find(x=>x.id===id('wm2FieldId').value),type=id('wm2FieldType').value,configuration={},min=id('wm2FieldMin').value.trim(),max=id('wm2FieldMax').value.trim();if(min!=='')configuration.min=min;if(max!=='')configuration.max=max;if(type==='workspaceReference'){configuration.targetWorkspaceId=id('wm2ReferenceTarget').value;configuration.relationshipType=id('wm2RelationshipType').value;configuration.selectionMode=id('wm2ReferenceSelection').value;const display=id('wm2ReferenceField').value.trim();if(display)configuration.targetFieldKey=display}if(type==='matrix'){configuration.rows=parseAxis(id('wm2MatrixRows').value);configuration.columns=parseAxis(id('wm2MatrixColumns').value);configuration.cellType=id('wm2MatrixCellType').value}if(['radio','singleSelect','multiSelect'].includes(type)){const picklistId=id('wm2FieldPicklist').value;if(!picklistId&&!f)throw new Error('Choose a Picklist from Picklist Manager.');if(picklistId){configuration.picklistId=picklistId;configuration.picklistMode=id('wm2PicklistMode').value;if(configuration.picklistMode==='filtered'){configuration.picklistFilterFieldKey=id('wm2PicklistFilterField').value;if(!configuration.picklistFilterFieldKey)throw new Error('Choose the field that controls the filtered Picklist.')}}else Object.assign(configuration,f?.configuration||{})}const base={sectionId:id('wm2FieldSection').value||null,label:id('wm2FieldLabel').value.trim(),description:id('wm2FieldDescription').value.trim(),fieldType:type,required:id('wm2FieldRequired').checked,helpText:id('wm2FieldHelp').value.trim(),placeholder:id('wm2FieldPlaceholder').value.trim(),width:id('wm2FieldWidth').value,screenVisible:id('wm2FieldScreen').checked,previewVisible:id('wm2FieldPreview').checked,printVisible:id('wm2FieldPrint').checked,searchable:id('wm2FieldSearch').checked,filterable:id('wm2FieldFilter').checked,configuration};state.detail=f?await api.updateField(f.id,{...base,version:f.version}):await api.addField(state.detail.id,{...base,fieldKey:id('wm2FieldKey').value.trim(),order:allFields().length+1,workspaceVersion:state.detail.version});closeModal();renderDetail();showToast('Field saved.')})}
async function copyField(fieldId){const f=allFields().find(x=>x.id===fieldId);if(!f)return;let key=(f.fieldKey+'Copy').slice(0,75),n=2;while(allFields().some(x=>x.fieldKey===key))key=(f.fieldKey+'Copy'+n++).slice(0,80);await safe(async()=>{const body={sectionId:f.sectionId,fieldKey:key,label:f.label+' Copy',description:f.description,fieldType:f.fieldType,required:false,defaultValue:f.defaultValue,helpText:f.helpText,placeholder:f.placeholder,width:f.width,order:allFields().length+1,screenVisible:f.screenVisible,previewVisible:f.previewVisible,printVisible:f.printVisible,searchable:f.searchable,filterable:f.filterable,configuration:f.configuration||{},workspaceVersion:state.detail.version};if((f.options||[]).length)body.options=f.options.map(x=>({value:x.value,label:x.label}));state.detail=await api.addField(state.detail.id,body);renderDetail();showToast('Field copied as custom metadata.')})}
async function archiveField(fieldId){const f=allFields().find(x=>x.id===fieldId);if(!f||!confirm('Archive field "'+f.label+'"? Its metadata remains recoverable.'))return;await safe(async()=>{state.detail=await api.updateField(f.id,{archived:true,version:f.version});renderDetail()})}
async function moveField(sectionId,i,d){const fields=sectionId?state.detail.sections.find(x=>x.id===sectionId)?.fields||[]:state.detail.unassignedFields||[],j=i+d;if(j<0||j>=fields.length)return;await safe(async()=>{let one=fields[i],two=fields[j],next=await api.updateField(one.id,{order:two.order,version:one.version});two=allFields(next).find(x=>x.id===two.id);state.detail=await api.updateField(two.id,{order:one.order,version:two.version});renderDetail()})}
function preview(){const w=state.detail;openModal('Metadata Preview — '+w.pluralName,'<div class="notice"><b>Preview only.</b> This is not a live operational workspace and does not create record storage.</div>'+(w.sections||[]).filter(s=>s.enabled!==false&&s.screenVisible!==false).map(s=>'<div class="wm2-preview-section"><h3>'+ev(s.name)+'</h3><div class="wm2-preview-fields">'+(s.fields||[]).filter(f=>!f.archived&&f.screenVisible!==false).map(f=>'<div class="wm2-preview-field"><label>'+ev(f.label)+(f.required?' *':'')+'</label><div class="muted">'+ev(labels[f.fieldType]||f.fieldType)+'</div>'+(f.helpText?'<div class="wm2-help">'+ev(f.helpText)+'</div>':'')+((f.options||[]).length?'<div class="wm2-help">Options: '+f.options.map(o=>ev(o.label)).join(', ')+'</div>':'')+'</div>').join('')+'</div></div>').join(''))}
async function history(){try{const r=await api.versions(state.detail.id);openModal('Workspace Version History','<div class="notice">Read-only PostgreSQL snapshots. Operational records are not included.</div><div class="table-wrap"><table><thead><tr><th>Version</th><th>Reason</th><th>Actor</th><th>Time</th></tr></thead><tbody>'+((r.items||[]).map(x=>'<tr><td>'+ev(x.workspaceVersion)+'</td><td>'+ev(x.changeReason)+'</td><td>'+ev(x.createdBy||'System')+'</td><td>'+ev(x.createdAt)+'</td></tr>').join('')||'<tr><td colspan="4">No versions found.</td></tr>')+'</tbody></table></div>')}catch(e){alert(e.message)}}
async function resetPreview(){try{const p=await api.resetPreview(state.detail.id);openModal('Reset to Factory Configuration','<div class="notice"><b>Preview — no changes have been made.</b></div><div class="wm2-meta" style="margin:12px 0"><div>Factory version: <b>'+ev(p.factoryVersion)+'</b></div><div>System sections checked: <b>'+ev(p.systemSections)+'</b></div><div>System fields checked: <b>'+ev(p.systemFields)+'</b></div><div>Factory differences to restore: <b>'+ev(p.changes.length)+'</b></div><div>Custom sections preserved: <b>'+ev(p.customSections)+'</b></div><div>Custom fields preserved: <b>'+ev(p.customFields)+'</b></div></div><div class="notice"><b>Protected:</b> operational records and custom metadata are preserved. The reset is transactional and versioned.</div>'+(p.changes.length?'<ul>'+p.changes.map(x=>'<li>Restore '+ev(x.fieldKey)+' — '+ev(x.label)+'</li>').join('')+'</ul>':'<div class="muted">Factory-managed fields already match the current factory.</div>')+'<button class="btn danger" onclick="schoolHubWM2.confirmReset()">Confirm Factory Reset</button>')}catch(e){alert(e.message)}}
async function confirmReset(){if(!confirm('Reset this built-in workspace to its factory metadata? Operational records and custom fields will be preserved.'))return;await safe(async()=>{state.detail=await api.reset(state.detail.id,{version:state.detail.version,confirmed:true});closeModal();renderDetail();showToast('Factory metadata restored; operational records preserved.')})}
function modernStyle(){if(id('wm3Style'))return;const s=document.createElement('style');s.id='wm3Style';s.textContent='.wm3-shell{--wm3-blue:#0b66e4;--wm3-navy:#10213a;--wm3-bg:#f5f7fb;--wm3-line:#dde5f0;--wm3-muted:#617087;color:var(--wm3-navy)}.wm3-hero{background:#fff;border:1px solid var(--wm3-line);border-radius:14px;padding:22px 24px;margin-bottom:16px;box-shadow:0 6px 24px rgba(20,45,80,.05)}.wm3-hero-row,.wm3-section-head,.wm3-catalog-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.wm3-title{margin:0;font-size:27px;line-height:1.2;color:var(--wm3-navy)}.wm3-subtitle{color:var(--wm3-muted);margin-top:6px;max-width:760px}.wm3-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.wm3-tabs{display:flex;gap:4px;margin:20px -4px -22px;overflow-x:auto}.wm3-tab{border:0;border-bottom:3px solid transparent;background:transparent;color:#506079;padding:12px 14px;font-weight:700;white-space:nowrap;cursor:pointer}.wm3-tab:hover{color:var(--wm3-blue)}.wm3-tab.active{color:var(--wm3-blue);border-bottom-color:var(--wm3-blue)}.wm3-panel{background:#fff;border:1px solid var(--wm3-line);border-radius:14px;padding:20px;box-shadow:0 6px 24px rgba(20,45,80,.04)}.wm3-grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.wm3-field label{display:block;font-size:12px;font-weight:700;margin-bottom:6px;color:#34445b}.wm3-field input,.wm3-field textarea,.wm3-field select{width:100%;border:1px solid #ccd7e5;border-radius:8px;background:#fff;padding:10px 11px;color:var(--wm3-navy)}.wm3-field textarea{min-height:92px;resize:vertical}.wm3-field input:disabled{background:#f1f4f8;color:#65748a}.wm3-span-2{grid-column:span 2}.wm3-note{border:1px solid #cfe0fb;background:#f2f7ff;color:#28476e;border-radius:10px;padding:12px 14px;margin-bottom:16px}.wm3-list{border:1px solid var(--wm3-line);border-radius:12px;overflow:hidden}.wm3-list-head,.wm3-list-row{display:grid;grid-template-columns:minmax(190px,1.4fr) minmax(130px,.8fr) minmax(170px,1fr) auto;gap:12px;align-items:center;padding:11px 14px}.wm3-list-head{background:#f5f7fb;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;color:#68778d}.wm3-list-row{border-top:1px solid var(--wm3-line)}.wm3-list-row:hover{background:#f8fbff}.wm3-type{display:inline-block;border-radius:7px;padding:5px 9px;background:#e8f1ff;color:#0758c7;font-size:12px;font-weight:700}.wm3-visibility{font-size:12px;color:var(--wm3-muted)}.wm3-section-card{border:1px solid var(--wm3-line);border-radius:12px;margin-bottom:12px;overflow:hidden;background:#fff}.wm3-section-card.selected{border-color:#64a1ef;box-shadow:0 0 0 2px rgba(11,102,228,.08)}.wm3-section-title{padding:14px 16px;background:#f8fafd;display:flex;justify-content:space-between;gap:12px;align-items:center}.wm3-section-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:14px}.wm3-field-chip{border:1px solid var(--wm3-line);border-radius:8px;padding:10px 12px;display:flex;justify-content:space-between;gap:8px;background:#fff}.wm3-ready-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.wm3-ready-card{border:1px solid var(--wm3-line);border-radius:12px;padding:18px;background:#fff}.wm3-ready-card h3{margin:0 0 6px}.wm3-print-row{display:grid;grid-template-columns:minmax(180px,1fr) 120px 120px;gap:12px;align-items:center;padding:10px 12px;border-top:1px solid var(--wm3-line)}.wm3-switch{display:flex;align-items:center;gap:8px;font-size:12px}.wm3-status{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:5px 9px;background:#dcf8e8;color:#08783f;font-size:12px;font-weight:800}.wm3-status:before{content:"";width:7px;height:7px;border-radius:50%;background:#16a15d}.wm3-system{display:inline-block;border-radius:999px;padding:5px 9px;background:#edf2ff;color:#3852a3;font-size:12px;font-weight:700}.wm3-catalog{background:var(--wm3-bg);border-radius:14px;padding:18px}.wm3-catalog-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) repeat(4,minmax(130px,auto));gap:10px;margin:16px 0}.wm3-catalog-toolbar input,.wm3-catalog-toolbar select{border:1px solid #ccd7e5;border-radius:8px;background:#fff;padding:10px}.wm3-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.wm3-card{border:1px solid var(--wm3-line);border-radius:12px;background:#fff;padding:16px;text-align:left;color:var(--wm3-navy);cursor:pointer;min-height:154px;display:flex;flex-direction:column}.wm3-card:hover,.wm3-card:focus{border-color:var(--wm3-blue);box-shadow:0 8px 28px rgba(20,75,145,.12);outline:none}.wm3-card-top{display:flex;justify-content:space-between;gap:10px}.wm3-card-icon{width:36px;height:36px;border-radius:9px;background:#e9f2ff;color:var(--wm3-blue);display:grid;place-items:center;font-size:18px;font-weight:900}.wm3-card h3{font-size:16px;margin:11px 0 2px}.wm3-card p{font-size:13px;color:var(--wm3-muted);margin:8px 0;flex:1}.wm3-badges{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}.wm3-badge{border-radius:999px;background:#f0f4fa;color:#52637a;padding:4px 8px;font-size:11px}.wm3-badge.active{background:#dcf8e8;color:#08783f}.wm3-empty{padding:42px;text-align:center;color:var(--wm3-muted)}@media(max-width:1100px){.wm3-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.wm3-catalog-toolbar{grid-template-columns:1fr 1fr}.wm3-ready-grid{grid-template-columns:1fr}}@media(max-width:760px){.wm3-hero-row,.wm3-section-head,.wm3-catalog-head{display:block}.wm3-actions{justify-content:flex-start;margin-top:14px}.wm3-grid-2,.wm3-section-fields,.wm3-cards{grid-template-columns:1fr}.wm3-span-2{grid-column:auto}.wm3-list-head{display:none}.wm3-list-row{grid-template-columns:1fr}.wm3-catalog-toolbar{grid-template-columns:1fr}.wm3-print-row{grid-template-columns:1fr}.wm3-title{font-size:23px}}';document.head.appendChild(s)}
function completeStyle(){if(id('wm4Style'))return;const s=document.createElement('style');s.id='wm4Style';s.textContent='.wm3-field-group{border:1px solid var(--wm3-line);border-radius:13px;overflow:hidden;margin-top:14px;background:#fff}.wm3-field-group-head{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 15px;background:#f7faff;border-bottom:1px solid var(--wm3-line)}.wm3-field-group-head h4{margin:0;font-size:15px}.wm3-field-group .wm3-list{border:0;border-radius:0}.wm4-print{color:var(--wm3-navy)}.wm4-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.wm4-card{background:#fff;border:1px solid var(--wm3-line);border-radius:14px;padding:18px;box-shadow:0 6px 24px rgba(20,45,80,.04)}.wm4-full{margin-top:14px}.wm4-card-title{display:flex;gap:11px;align-items:flex-start}.wm4-card-title h4{font-size:17px;margin:0}.wm4-card-title p{color:var(--wm3-muted);font-size:12px;margin:3px 0 12px}.wm4-icon{width:32px;height:32px;display:grid;place-items:center;border-radius:9px;background:#e8f2ff;color:#0865df;font-size:18px;font-weight:900;flex:0 0 auto}.wm4-checks{display:grid;gap:6px}.wm4-check{display:flex;gap:9px;align-items:flex-start;padding:7px;border-radius:8px}.wm4-check:hover{background:#f7faff}.wm4-check input{margin-top:3px}.wm4-check span,.wm4-check small,.wm4-setting-line small,.wm4-brand-preview small{display:block}.wm4-check small,.wm4-setting-line small,.wm4-brand-preview small{color:var(--wm3-muted);font-size:11px;margin-top:2px}.wm4-setting-line{display:flex;gap:10px;align-items:center;padding-top:12px;margin-top:12px;border-top:1px solid var(--wm3-line)}.wm4-toggle{position:relative;display:inline-flex}.wm4-toggle input{position:absolute;opacity:0}.wm4-toggle span{width:40px;height:23px;border-radius:20px;background:#b9c5d5;position:relative;transition:.18s}.wm4-toggle span:after{content:"";position:absolute;width:17px;height:17px;left:3px;top:3px;border-radius:50%;background:#fff;box-shadow:0 1px 3px #0003;transition:.18s}.wm4-toggle input:checked+span{background:#0b66e4}.wm4-toggle input:checked+span:after{transform:translateX(17px)}.wm4-brand-preview{display:flex;gap:12px;align-items:center;border:1px solid var(--wm3-line);border-radius:11px;padding:13px;margin:4px 0 13px;background:#f9fbfe}.wm4-brand-preview img{width:72px;height:46px;object-fit:contain}.wm4-logo-placeholder{font-size:18px;font-weight:900;color:#0b66e4;padding:10px}.wm4-label{display:block;font-size:11px;font-weight:700;color:#46566c;margin-top:8px}.wm4-label input,.wm4-label select{display:block;width:100%;margin-top:4px;border:1px solid #ccd7e5;border-radius:8px;padding:8px;background:#fff;color:var(--wm3-navy)}.wm4-mini-grid,.wm4-margin-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.wm4-margin-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.wm4-subhead{display:block;font-size:12px;margin-top:13px}.wm4-watermark-layout{display:grid;grid-template-columns:160px 1fr;gap:14px;margin-top:12px}.wm4-watermark-preview{height:210px;border:1px solid var(--wm3-line);border-radius:9px;background:linear-gradient(#fff,#f7f9fc);display:grid;place-items:center;overflow:hidden}.wm4-watermark-preview span{color:#456080;font-weight:800;white-space:nowrap}.wm4-section-head,.wm4-section-row{display:grid;grid-template-columns:28px 30px minmax(180px,1fr) 110px 180px;gap:10px;align-items:center;padding:9px 10px}.wm4-section-head{border-bottom:1px solid var(--wm3-line);color:var(--wm3-muted);font-size:10px;font-weight:800;text-transform:uppercase}.wm4-section-row{border-bottom:1px solid var(--wm3-line)}.wm4-section-row:last-child{border-bottom:0}.wm4-section-row select{border:1px solid #ccd7e5;border-radius:7px;padding:7px;background:#fff}.wm4-grip{color:#8a99ae;font-size:18px}.wm4-designer-empty{min-height:110px;border:1px dashed #b8c8dc;border-radius:11px;background:#f8fbff;display:grid;place-items:center;align-content:center;color:#52637a;margin-top:10px}.wm4-designer-empty span{display:block;font-size:12px;margin-top:4px}@media(max-width:1050px){.wm4-grid{grid-template-columns:1fr}.wm4-watermark-layout{grid-template-columns:130px 1fr}}@media(max-width:700px){.wm3-field-group-head{display:block}.wm4-mini-grid,.wm4-margin-grid,.wm4-watermark-layout{grid-template-columns:1fr}.wm4-section-head{display:none}.wm4-section-row{grid-template-columns:24px 24px 1fr}.wm4-section-row label,.wm4-section-row select{grid-column:3}}';document.head.appendChild(s)}
function tabButton(key,label){return '<button type="button" class="wm3-tab '+(state.tab===key?'active':'')+'" aria-selected="'+(state.tab===key?'true':'false')+'" onclick="schoolHubWM2.setTab(\''+key+'\')">'+label+'</button>'}
function workspaceHero(w){const actions='<button class="btn" onclick="schoolHubWM2.loadCatalog()">← All Workspaces</button><button class="btn" onclick="schoolHubWM2.preview()">Preview Workspace</button><button class="btn" onclick="schoolHubWM2.history()">Version History</button>'+(w.system&&has('workspaces:reset')?'<button class="btn danger" onclick="schoolHubWM2.resetPreview()">Reset to Factory</button>':'');return '<div class="wm3-hero"><div class="wm3-hero-row"><div><div class="wm2-help">Administration / Workspace Manager / '+ev(w.pluralName)+'</div><h2 class="wm3-title">'+ev(w.pluralName)+' Workspace</h2><div class="wm3-subtitle">'+ev(w.description||'Configure this workspace and how its fields are presented.')+'</div><div class="wm3-badges" style="margin-top:10px"><span class="wm3-status">'+ev(w.status)+'</span><span class="wm3-system">'+(w.system?'System workspace':'Custom workspace')+'</span><span class="wm3-badge">Metadata v'+ev(w.definitionVersion)+'</span></div></div><div class="wm3-actions">'+actions+'</div></div><div class="wm3-tabs" role="tablist">'+tabButton('general','General')+tabButton('fields','Fields')+tabButton('layout','Layout')+tabButton('relationships','Relationships')+tabButton('print','Print & Branding')+'</div></div>'}
function generalTab(w){const can=has('workspaces:configure');return '<div class="wm3-panel"><div class="wm3-section-head"><div><h3 style="margin:0">General Settings</h3><div class="wm3-subtitle">Define the identity and safe presentation settings for this workspace.</div></div>'+(can?'<button class="btn primary" onclick="schoolHubWM2.saveGeneral()">Save Changes</button>':'')+'</div><div class="wm3-grid-2" style="margin-top:18px"><div class="wm3-field"><label>Workspace Name</label><input id="wm3Singular" value="'+ev(w.name)+'" '+(can?'':'disabled')+'></div><div class="wm3-field"><label>Workspace ID</label><input value="'+ev(w.workspaceKey)+'" disabled><span class="wm2-help">Stable system identifier; it cannot be renamed.</span></div><div class="wm3-field wm3-span-2"><label>Description</label><textarea id="wm3Description" '+(can?'':'disabled')+'>'+ev(w.description)+'</textarea></div><div class="wm3-field"><label>Category</label><input id="wm3Category" value="'+ev(w.category)+'" '+(can?'':'disabled')+'></div><div class="wm3-field"><label>Icon</label><input id="wm3Icon" value="'+ev(w.icon||'')+'" placeholder="Optional icon name" '+(can?'':'disabled')+'></div><div class="wm3-field"><label>Singular Record Name</label><input value="'+ev(w.name)+'" disabled><span class="wm2-help">Uses Workspace Name in the current schema.</span></div><div class="wm3-field"><label>Plural Record Name</label><input id="wm3Plural" value="'+ev(w.pluralName)+'" '+(can?'':'disabled')+'></div><div class="wm3-field"><label>Workspace Type</label><input value="'+ev(w.workspaceType)+'" disabled></div><div class="wm3-field"><label>Lifecycle</label><select id="wm3Status" '+((can&&!w.system)?'':'disabled')+'>'+['Draft','Active','Archived'].map(x=>'<option '+(w.status===x?'selected':'')+'>'+x+'</option>').join('')+'</select><span class="wm2-help">Built-in workspaces remain Active.</span></div></div><div class="wm3-note" style="margin-top:18px"><b>Existing records are protected.</b> These settings update Workspace metadata only and do not rename tables, routes, record IDs, or operational data.</div>'+(!w.system?'<div style="margin-top:14px">'+lifecycleHtml(w)+'</div>':'')+'</div>'}
function fieldsTab(w){const fields=allFields(w),can=has('workspaces:configure');const rows=fields.map(f=>{const section=w.sections.find(s=>s.id===f.sectionId),index=section?(section.fields||[]).findIndex(x=>x.id===f.id):-1,total=section?.fields?.length||0,protectedArchive=(f.protectedProperties||[]).includes('archived');return '<div class="wm3-list-row"><div><b>'+ev(f.label)+'</b>'+(f.required?' <span class="danger-text">*</span>':'')+' '+(f.system?'<span class="wm3-system">Existing field</span>':'')+(f.archived?'<span class="wm3-badge">Archived</span>':'')+'<span class="wm2-help">'+ev(f.fieldKey)+' · '+ev(section?.name||'Unassigned')+'</span></div><div><span class="wm3-type">'+ev(labels[f.fieldType]||f.fieldType)+'</span></div><div class="wm3-visibility">'+[f.screenVisible?'Form':'',f.previewVisible?'Preview':'',f.printVisible?'Print':'',f.searchable?'Search':'',f.filterable?'Filter':''].filter(Boolean).join(' · ')+'</div><div class="wm3-actions">'+(can?'<button class="btn small" onclick="schoolHubWM2.openField(\''+ev(f.id)+'\')">Edit</button><button class="btn small" onclick="schoolHubWM2.copyField(\''+ev(f.id)+'\')">Copy</button>'+(section?'<button class="btn small" '+(index<=0?'disabled':'')+' onclick="schoolHubWM2.moveField(\''+ev(section.id)+'\','+index+',-1)">Up</button><button class="btn small" '+(index<0||index===total-1?'disabled':'')+' onclick="schoolHubWM2.moveField(\''+ev(section.id)+'\','+index+',1)">Down</button>':'')+(!f.archived&&!protectedArchive?'<button class="btn small danger" onclick="schoolHubWM2.archiveField(\''+ev(f.id)+'\')">Archive</button>':''):'')+'</div></div>'}).join('');return '<div class="wm3-panel"><div class="wm3-section-head"><div><h3 style="margin:0">Existing &amp; Custom Fields</h3><div class="wm3-subtitle">Existing module fields and custom metadata fields for this workspace.</div></div>'+(can?'<div class="wm3-actions"><button class="btn" onclick="schoolHubWM2.openSection()">+ Add Section</button><button class="btn primary" onclick="schoolHubWM2.openField()">+ Add Field</button></div>':'')+'</div><div class="wm3-note" style="margin-top:16px"><b>'+fields.length+' fields found.</b> Existing fields are factory-mapped and protected; safe display settings remain configurable.</div><div class="wm3-list"><div class="wm3-list-head"><span>Field</span><span>Type</span><span>Used in</span><span>Actions</span></div>'+(rows||'<div class="wm3-empty">No fields are mapped yet.</div>')+'</div></div>'}
function layoutTab(w){const can=has('workspaces:configure'),total=(w.sections||[]).length;const cards=(w.sections||[]).map((s,i)=>'<div class="wm3-section-card '+(s.enabled===false?'':'selected')+'"><div class="wm3-section-title"><div><b>'+ev(s.name)+'</b>'+(s.enabled===false?' <span class="wm3-badge">Archived</span>':'')+'<span class="wm2-help">'+ev(s.sectionKey)+' · '+ev(s.layoutColumns)+' column layout</span></div><div class="wm3-actions">'+(s.system?'<span class="wm3-system">System</span>':'<span class="wm3-badge">Custom</span>')+(can?'<button class="btn small" onclick="schoolHubWM2.openSection(\''+ev(s.id)+'\')">Configure</button><button class="btn small" '+(i===0?'disabled':'')+' onclick="schoolHubWM2.moveSection('+i+',-1)">Up</button><button class="btn small" '+(i===total-1?'disabled':'')+' onclick="schoolHubWM2.moveSection('+i+',1)">Down</button>'+(!s.system&&s.enabled!==false?'<button class="btn small danger" onclick="schoolHubWM2.archiveSection(\''+ev(s.id)+'\')">Archive</button>':'')+'<button class="btn primary small" onclick="schoolHubWM2.openField(null,\''+ev(s.id)+'\')">+ Field</button>':'')+'</div></div><div class="wm3-section-fields">'+((s.fields||[]).filter(f=>!f.archived).map(f=>'<div class="wm3-field-chip"><span>'+ev(f.label)+'</span><span class="wm3-type">'+ev(labels[f.fieldType]||f.fieldType)+'</span></div>').join('')||'<div class="wm2-help">No mapped fields in this section.</div>')+'</div></div>').join('');return '<div id="wmDashboardEditor" data-workspace-key="'+ev(w.workspaceKey)+'"></div><div class="wm3-panel"><div class="wm3-section-head"><div><h3 style="margin:0">Section Layout Builder</h3><div class="wm3-subtitle">Configure independent Create, Edit, Record, and Print layouts for every section.</div></div>'+(can?'<button class="btn primary" onclick="schoolHubWM2.openSection()">+ Add Section</button>':'')+'</div><div class="wm3-actions" style="justify-content:flex-start;margin:16px 0"><span class="wm3-type">Create form</span><span class="wm3-badge">Edit form</span><span class="wm3-badge">Record view</span><span class="wm3-badge">Print view</span></div><div class="wm3-note"><b>Independent layouts are active.</b> Open Section settings to configure visibility, order and columns for each view. Role controls use Users & Roles and do not create a Workspace Permissions tab.</div>'+(cards||'<div class="wm3-empty">No sections configured.</div>')+'</div>'}
