const priorShow=window.showTab,priorAll=window.renderAll,priorSettingsOpen=window.uiA1Open,priorSettingsSearch=window.uiA1Search;window.showTab=function(tab){if(tab==='workspaceManager'){const r=priorShow.call(this,'settings');setTimeout(()=>{ensure();if(integrateSettings())openSettings()},0);return r}const r=priorShow.apply(this,arguments);setTimeout(ensure,0);return r};window.renderAll=function(){const r=priorAll.apply(this,arguments);setTimeout(ensure,0);return r};if(typeof priorSettingsOpen==='function')window.uiA1Open=function(page,opts){if(page==='workspaces')return openSettings(opts);return priorSettingsOpen.apply(this,arguments)};if(typeof priorSettingsSearch==='function')window.uiA1Search=function(q){priorSettingsSearch.apply(this,arguments);const term=String(q||'').trim().toLowerCase(),box=id('uia1SearchResults'),match=(settingsPage.title+' '+settingsPage.desc+' '+settingsPage.cat+' '+settingsPage.keys).toLowerCase().includes(term);if(!box||!term||!match)return;if(!box.querySelector('[data-wm2-search]')){const b=document.createElement('button');b.type='button';b.dataset.wm2Search='true';b.onclick=()=>{openSettings();const input=id('uia1SettingsSearch');if(input)input.value='';window.uiA1Search('')};b.innerHTML='<span class="uia1-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="4" y="4" width="16" height="16" rx="3"/></svg></span><span><b>Workspace Manager</b><small>Data &amp; System &mdash; '+settingsPage.desc+'</small></span>';box.prepend(b)}};
